// ==UserScript==
// @name         BankAmeriDeals Lite
// @namespace    https://github.com/yangzichao/card-offer-hub
// @version      1.0.0
// @description  Manually scan and activate ordinary card-linked BankAmeriDeals with verified results
// @author       Zichao Yang
// @match        https://deals.merchant-rewards.com/*
// @grant        GM_getValue
// @grant        GM_setValue
// @noframes
// @run-at       document-idle
// @homepageURL  https://github.com/yangzichao/card-offer-hub/tree/main/issuers/bank-of-america/bofa-offer-lite
// @supportURL   https://github.com/yangzichao/card-offer-hub/issues
// @updateURL    https://raw.githubusercontent.com/yangzichao/card-offer-hub/main/dist/bofa-offer-lite.user.js
// @downloadURL  https://raw.githubusercontent.com/yangzichao/card-offer-hub/main/dist/bofa-offer-lite.user.js
// ==/UserScript==
// Generated from issuers/bank-of-america/bofa-offer-lite/src by "npm run build". Do not edit this file.
// Installing from https://raw.githubusercontent.com/yangzichao/card-offer-hub/main/dist/bofa-offer-lite.user.js lets Tampermonkey update it on its own.

(function () {
    'use strict';

    // Source: core/state.js
    const SETTINGS = {
        id: "bofa-offer-lite", name: "BankAmeriDeals Lite", version: "1.0.0",
        gapMilliseconds: 500, timeoutMilliseconds: 45000, pageSize: 24,
        defaultCooldownMilliseconds: 300000
    };
    const state = {
        busy: false, stopRequested: false, needsScan: true, consent: false,
        sessionToken: '', proximity: null, offers: [], confirmed: 0,
        nextRequestAt: 0, cooldownUntil: 0, storageError: '',
        status: 'Nothing runs automatically. Scan the current signed-in Deals profile first.',
        panel: null, collapsed: false
    };
    function updateStatus(message) { state.status = message; renderPanel(); }
    function ensureRunning() {
        if (state.stopRequested) throw new Error('Stopped. Scan again before activating more offers.');
        if (location.origin !== 'https://deals.merchant-rewards.com') throw new Error('Open the official Deals website.');
        if (!state.sessionToken || currentSessionToken() !== state.sessionToken) {
            throw new Error('The signed-in session changed. Scan again.');
        }
    }
    function stopRun() {
        state.stopRequested = true;
        updateStatus('Stopping after the current request. Any unverified activation requires a new scan.');
    }

    // Source: core/storage.js
    // Only request deadlines are persisted, never credentials, offers or location.
    function restorePacing() {
        try {
            const saved = GM_getValue(`${SETTINGS.id}:pacing`, null);
            if (saved === null) return;
            if (saved.schemaVersion !== 1 || !Number.isFinite(saved.nextRequestAt)
                || !Number.isFinite(saved.cooldownUntil)) throw new Error('Unsupported snapshot');
            state.nextRequestAt = Math.max(state.nextRequestAt, saved.nextRequestAt);
            state.cooldownUntil = Math.max(state.cooldownUntil, saved.cooldownUntil);
        } catch {
            state.storageError = 'Cannot read pacing storage. Stored data was preserved; fix storage before running.';
        }
    }
    function savePacing() {
        if (state.storageError) throw new Error(state.storageError);
        try {
            GM_setValue(`${SETTINGS.id}:pacing`, {
                schemaVersion: 1, nextRequestAt: state.nextRequestAt, cooldownUntil: state.cooldownUntil
            });
        } catch {
            state.storageError = 'Cannot save pacing storage. Further requests are blocked; fix storage and reload.';
            throw new Error(state.storageError);
        }
    }

    // Source: api/session.js
    function currentSessionToken() {
        let token;
        let claims;
        try {
            token = new URLSearchParams(location.search).get('token') || localStorage.getItem('LS_TOKEN');
            if (typeof token !== 'string' || token.split('.').length !== 3) throw new Error('Missing token');
            const encoded = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
            claims = JSON.parse(atob(encoded.padEnd(Math.ceil(encoded.length / 4) * 4, '=')));
        } catch { throw new Error('No readable Deals session. Sign in through Bank of America and scan again.'); }
        if (!Number.isFinite(claims.exp) || claims.exp * 1000 <= Date.now()) {
            throw new Error('Deals session expired. Sign in again.');
        }
        // This adapter implements the observed modern API, not /api-legacy.
        if (claims.featureFlags?.dxlEnabled !== true) throw new Error('This Deals session does not use the supported modern API.');
        return token;
    }

    // Source: api/transport.js
    function retryAfterMilliseconds(value) {
        if (typeof value === 'string' && /^\d+(?:\.\d+)?$/.test(value.trim())) return Number(value) * 1000;
        const deadline = typeof value === 'string' ? Date.parse(value) : NaN;
        return Number.isFinite(deadline) ? Math.max(0, deadline - Date.now()) : SETTINGS.defaultCooldownMilliseconds;
    }
    async function requestJson(path, method = 'POST', body) {
        const allowed = (path === '/geo' && method === 'GET')
            || (['/api/offers-search', '/api/offers-details'].includes(path) && method === 'POST')
            || (/^\/api\/activate-offer\/\d+$/.test(path) && method === 'PUT' && body === undefined);
        if (!allowed) throw new Error('Unsupported Deals request.');
        if (state.storageError) throw new Error(state.storageError);
        if (Date.now() < state.cooldownUntil) throw new Error('Rate limited. Wait for the saved cooldown to end before scanning.');
        while (Date.now() < state.nextRequestAt) {
            ensureRunning();
            await new Promise(resolve => setTimeout(resolve, Math.min(250, state.nextRequestAt - Date.now())));
        }
        ensureRunning();
        state.nextRequestAt = Date.now() + SETTINGS.timeoutMilliseconds + SETTINGS.gapMilliseconds;
        savePacing();
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), SETTINGS.timeoutMilliseconds);
        try {
            const headers = path === '/geo' ? {} : { 'X-Cardholder-Token': state.sessionToken };
            if (body !== undefined) headers['Content-Type'] = 'application/json';
            const response = await fetch(path, {
                method, headers, body: body === undefined ? undefined : JSON.stringify(body),
                credentials: 'same-origin', redirect: 'error', signal: controller.signal
            });
            if (response.status === 429) {
                state.cooldownUntil = Math.max(state.cooldownUntil,
                    Date.now() + retryAfterMilliseconds(response.headers.get('Retry-After')));
            }
            const responseText = await response.text();
            if (response.status === 429) throw new Error('HTTP 429. Cooling down; no automatic retry.');
            if (!response.ok) throw new Error(`Deals returned HTTP ${response.status}. Scan again after resolving the error.`);
            try { return JSON.parse(responseText); }
            catch { throw new Error('Unexpected Deals response. Sign in and scan again.'); }
        } catch (error) {
            if (error.name === 'AbortError') throw new Error('Request timed out. Activation may be unconfirmed; scan again.');
            if (error instanceof TypeError) throw new Error('Network failure. Activation may be unconfirmed; scan again.');
            throw error;
        } finally {
            clearTimeout(timeout);
            state.nextRequestAt = Date.now() + SETTINGS.gapMilliseconds;
            savePacing();
        }
    }

    // Source: api/contracts.js
    function normalizeLocation(payload) {
        if (!Number.isFinite(payload?.latitude) || Math.abs(payload.latitude) > 90
            || !Number.isFinite(payload?.longitude) || Math.abs(payload.longitude) > 180) {
            throw new Error('Deals did not return a valid location. Scan stopped.');
        }
        return { latitude: payload.latitude, longitude: payload.longitude };
    }
    function normalizeOffer(raw) {
        if (!raw || typeof raw.offer_id !== 'string' || !/^\d+$/.test(raw.offer_id)
            || (raw.id !== undefined && raw.id !== raw.offer_id)
            || typeof raw.is_activated !== 'boolean') throw new Error('Unrecognized offer identity or activation state.');
        let reason = '';
        if (raw.is_activated) reason = 'Already activated';
        else if (raw.type !== 'CARD_LINKED') reason = 'Not an ordinary card-linked offer';
        else if (raw.activation_required !== true) reason = 'No explicit activation required';
        else if (raw.activation_type !== 'CLICK') reason = 'Shopping link / unsupported activation';
        else if (!Array.isArray(raw.activation_triggers) || raw.activation_triggers.length !== 1
            || raw.activation_triggers[0] !== 'OFFER_DETAILS_CLICK') reason = 'Unsupported activation trigger';
        return {
            id: raw.offer_id, name: typeof raw.merchant_name === 'string' ? raw.merchant_name : 'Merchant',
            headline: typeof raw.headline === 'string' ? raw.headline : '',
            eligible: !reason, activated: raw.is_activated, reason, result: ''
        };
    }
    function normalizePage(payload) {
        if (!payload || !Array.isArray(payload.offers) || !Number.isSafeInteger(payload.total)
            || payload.total < 0 || payload.total > 10000 || payload.user_information_available === false
            || payload.offers.length > SETTINGS.pageSize) throw new Error('Unrecognized or incomplete Deals search response.');
        return { offers: payload.offers.map(normalizeOffer), total: payload.total };
    }
    function normalizeDetail(payload, expectedId) {
        const offer = normalizeOffer(payload?.offer);
        if (offer.id !== expectedId) throw new Error('Offer detail identity mismatch. Activation unconfirmed; scan again.');
        return offer;
    }

    // Source: workflows/runner.js
    async function runExclusive(action) {
        if (state.busy) return;
        state.busy = true;
        state.stopRequested = false;
        renderPanel();
        try {
            if (!navigator.locks?.request) throw new Error('A browser with Web Locks is required. Use current Chrome.');
            await navigator.locks.request(SETTINGS.id, { ifAvailable: true }, async lock => {
                if (!lock) throw new Error('This script is running in another tab.');
                restorePacing();
                if (state.storageError) throw new Error(state.storageError);
                await action();
            });
        } catch (error) {
            state.needsScan = true;
            state.consent = false;
            updateStatus(error.message);
        } finally { state.busy = false; renderPanel(); }
    }

    // Source: workflows/offers.js
    async function scanOffers() {
        return runExclusive(async () => {
            state.needsScan = true;
            state.consent = false;
            state.offers = [];
            state.confirmed = 0;
            state.sessionToken = currentSessionToken();
            updateStatus('Reading current Deals location…');
            state.proximity = normalizeLocation(await requestJson('/geo', 'GET'));
            const collected = new Map();
            let expectedTotal = null;
            for (let offset = 0; ; offset += SETTINGS.pageSize) {
                updateStatus(`Scanning offers: ${collected.size} loaded…`);
                const page = normalizePage(await requestJson('/api/offers-search', 'POST', {
                    apply_filter: {}, proximity_target: state.proximity, sort_by: 'merchant_name_asc',
                    page_size: SETTINGS.pageSize, page_offset: offset
                }));
                ensureRunning();
                if (expectedTotal !== null && expectedTotal !== page.total) throw new Error('Offer list changed during pagination. Scan again.');
                expectedTotal = page.total;
                for (const offer of page.offers) {
                    if (collected.has(offer.id)) throw new Error('Repeated offer during pagination. Scan again.');
                    collected.set(offer.id, offer);
                }
                if (collected.size > expectedTotal) throw new Error('Inconsistent offer count. Scan again.');
                if (collected.size === expectedTotal) break;
                if (page.offers.length !== SETTINGS.pageSize) throw new Error('Incomplete offer page. Scan again.');
            }
            state.offers = [...collected.values()];
            state.needsScan = false;
            const available = state.offers.filter(offer => offer.eligible).length;
            updateStatus(`Scan complete: ${available} eligible, ${state.offers.length - available} skipped. Upside offers are excluded.`);
        });
    }
    async function fetchOfferDetail(id) {
        return normalizeDetail(await requestJson('/api/offers-details', 'POST', {
            offer_id: id, proximity_target: state.proximity
        }), id);
    }
    async function activateOffers() {
        if (state.needsScan || !state.consent) return;
        return runExclusive(async () => {
            ensureRunning();
            const queue = state.offers.filter(offer => offer.eligible && !offer.activated);
            state.needsScan = true;
            state.confirmed = 0;
            for (const offer of queue) {
                updateStatus(`Checking offer ${state.confirmed + 1}/${queue.length}…`);
                const current = await fetchOfferDetail(offer.id);
                ensureRunning();
                if (!current.eligible) {
                    Object.assign(offer, current);
                    throw new Error('Offer eligibility changed since scanning. Scan again before continuing.');
                }
                offer.result = 'Unconfirmed';
                updateStatus(`Activating offer ${state.confirmed + 1}/${queue.length}…`);
                const result = await requestJson(`/api/activate-offer/${offer.id}`, 'PUT');
                if (result?.ok !== true) throw new Error('Activation not explicitly confirmed. Scan again.');
                updateStatus('Activation accepted; verifying saved state…');
                const verified = await fetchOfferDetail(offer.id);
                ensureRunning();
                if (!verified.activated) throw new Error('Activation readback is unconfirmed. Scan again.');
                Object.assign(offer, verified, { result: 'Confirmed' });
                state.confirmed++;
            }
            state.consent = false;
            updateStatus(`Finished: ${state.confirmed}/${queue.length} activations confirmed by readback. Scan again to refresh.`);
        });
    }

    // Source: ui/panel.js
    function mountPanel() {
        if (document.getElementById(SETTINGS.id)) return;
        const host = document.createElement('div');
        host.id = SETTINGS.id;
        const root = host.attachShadow({ mode: 'open' });
        root.innerHTML = `<style>
            :host{all:initial;font:13px/1.45 system-ui;color:#172b45;position:fixed;right:18px;bottom:18px;z-index:2147483647}
            section{width:min(380px,calc(100vw - 36px));background:#fff;border:1px solid #c9d5e3;border-radius:12px;box-shadow:0 8px 32px #10254030;overflow:hidden}
            header{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:#f0f5fb;font-weight:700}
            main{padding:14px}p{margin:0 0 12px}button{font:inherit;padding:8px 12px;border:1px solid #aabbd0;border-radius:6px;background:#f6f9ff;cursor:pointer}
            button:disabled{opacity:.45;cursor:default}.actions{display:flex;gap:8px;margin:12px 0;flex-wrap:wrap}label{display:flex;gap:8px;align-items:flex-start}
            [role=status]{white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f6fb;padding:10px;border-radius:6px}.offers{max-height:210px;overflow:auto;margin-top:12px}
            .offer{border-top:1px solid #e1e7ef;padding:8px 0;overflow-wrap:anywhere}.muted{color:#53657a;font-size:12px}[hidden]{display:none!important}
        </style><section aria-label="BankAmeriDeals controls"><header><span></span><button aria-label="Minimize Deals panel">−</button></header><main>
            <p>Current signed-in Deals profile only. Shopping-link and Upside offers are excluded. Activation may start an expiry window; review terms first.</p>
            <label><input type="checkbox" aria-label="Confirm activation for current Deals profile">Activate all eligible offers in this profile</label>
            <div class="actions"><button aria-label="Scan Deals offers">Scan</button><button aria-label="Activate eligible Deals offers">Activate all</button><button aria-label="Stop Deals activation">Stop</button></div>
            <p role="status" aria-live="polite"></p><div class="muted">0.5s between completed requests · no automatic retries</div><div class="offers"></div>
        </main></section>`;
        state.panel = root;
        root.querySelector('header span').textContent = `${SETTINGS.name} · ${SETTINGS.version}`;
        root.querySelector('header button').onclick = () => { state.collapsed = !state.collapsed; renderPanel(); };
        root.querySelector('input').onchange = event => { state.consent = event.target.checked; renderPanel(); };
        root.querySelector('[aria-label="Scan Deals offers"]').onclick = scanOffers;
        root.querySelector('[aria-label="Activate eligible Deals offers"]').onclick = activateOffers;
        root.querySelector('[aria-label="Stop Deals activation"]').onclick = stopRun;
        document.body.appendChild(host);
        renderPanel();
    }

    // Source: ui/render.js
    function renderPanel() {
        const root = state.panel;
        if (!root) return;
        root.querySelector('main').hidden = state.collapsed;
        const toggle = root.querySelector('header button');
        toggle.textContent = state.collapsed ? '+' : '−';
        toggle.setAttribute('aria-label', state.collapsed ? 'Expand Deals panel' : 'Minimize Deals panel');
        root.querySelector('[role=status]').textContent = state.storageError || state.status;
        root.querySelector('input').checked = state.consent;
        root.querySelector('input').disabled = state.busy || state.needsScan;
        root.querySelector('[aria-label="Scan Deals offers"]').disabled = state.busy || !!state.storageError;
        root.querySelector('[aria-label="Activate eligible Deals offers"]').disabled = state.busy || state.needsScan
            || !state.consent || !!state.storageError || !state.offers.some(offer => offer.eligible && !offer.activated);
        root.querySelector('[aria-label="Stop Deals activation"]').disabled = !state.busy;
        const list = root.querySelector('.offers');
        list.replaceChildren();
        for (const offer of state.offers) {
            const row = document.createElement('div');
            row.className = 'offer';
            row.textContent = `${offer.name} — ${offer.headline}\n${offer.result || offer.reason || 'Eligible'}`;
            list.appendChild(row);
        }
    }

    // Source: initialize.js
    // --- Init ---
    restorePacing();
    mountPanel();
})();
